// The "Myths & facts" dialog: common claims answered from the map's own event cards.
// Loaded on first use, like the About dialog. Each answer links the cards that carry the
// evidence, so every claim stays one click from its sources.

import type { Myth } from '../data/mythTypes.ts';
import type { HistoricalEvent } from '../data/types.ts';
import { el } from '../dom.ts';
import { selectEvent } from '../timeline/navigate.ts';
import { onThisDaySection } from '../list/onThisDay.ts';

let dialog: HTMLDialogElement | null = null;

const eventsOf = (byId: ReadonlyMap<string, HistoricalEvent>): HistoricalEvent[] => [...byId.values()];

function build(myths: readonly Myth[], eventById: ReadonlyMap<string, HistoricalEvent>): HTMLDialogElement {
  const node = el('dialog', 'about myths');
  node.setAttribute('aria-labelledby', 'myths-title');

  const title = el('h2', 'about__title', 'Myths & facts');
  title.id = 'myths-title';

  const intro = el(
    'p',
    '',
    'Short answers to claims you will meet, each built from this map’s own event cards. Open the linked cards for the sources; where accounts differ, the card shows each view with attribution.',
  );

  const today = onThisDaySection(eventsOf(eventById));
  const list = el('div', 'myths__list');
  for (const myth of myths) {
    const item = el('details', 'myths__item');
    const head = el('summary', 'myths__claim');
    head.append(el('span', 'myths__q', 'Claim'), ` ${myth.myth}`);
    item.append(head);

    const body = el('div', 'myths__answer');
    if (myth.status === 'needs-review') {
      const tag = el('p', '');
      const review = el('span', 'tag tag--review', 'Under review');
      review.title = 'This answer has not yet been fully checked against the linked cards';
      tag.append(review);
      body.append(tag);
    }
    body.append(el('p', '', myth.answer));

    const links = el('p', 'myths__links');
    links.append(el('strong', '', 'See it on the map: '));
    let linked = 0;
    for (const id of myth.eventIds) {
      const event = eventById.get(id);
      if (!event) continue;
      if (linked > 0) links.append(' · ');
      const go = el('button', 'link-button', event.title);
      go.type = 'button';
      go.addEventListener('click', () => {
        dialog?.close();
        selectEvent(event);
      });
      links.append(go);
      linked += 1;
    }
    if (linked > 0) body.append(links);
    item.append(body);
    list.append(item);
  }

  const close = el('button', 'btn about__close', 'Close');
  close.type = 'button';
  close.addEventListener('click', () => node.close());

  node.append(title, intro);
  if (today) node.append(today);
  node.append(list, close);
  node.addEventListener('click', (e) => {
    if (e.target === node) node.close();
  });
  document.body.append(node);
  return node;
}

export function openMyths(myths: readonly Myth[], events: readonly HistoricalEvent[]): void {
  if (myths.length === 0) return;
  if (!dialog) dialog = build(myths, new Map(events.map((e) => [e.id, e])));
  dialog.showModal();
}
